CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT UNIQUE NOT NULL, pass TEXT NOT NULL, nome TEXT NOT NULL, sexo TEXT NOT NULL, created INTEGER NOT NULL, rec TEXT);
CREATE TABLE IF NOT EXISTS sessions(th TEXT PRIMARY KEY, uid INTEGER NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS docs(uid INTEGER NOT NULL, name TEXT NOT NULL, json TEXT NOT NULL, t INTEGER NOT NULL, PRIMARY KEY(uid, name));
CREATE TABLE IF NOT EXISTS photos(id TEXT PRIMARY KEY, uid INTEGER NOT NULL, pose TEXT NOT NULL, d TEXT NOT NULL, ts INTEGER NOT NULL, u TEXT NOT NULL, t TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS photos_uid ON photos(uid);
CREATE TABLE IF NOT EXISTS doc_hist(uid INTEGER NOT NULL, name TEXT NOT NULL, json TEXT NOT NULL, t INTEGER NOT NULL, PRIMARY KEY(uid, name, t));
